import { NgModule } from '@angular/core';
import { Route, RouterModule } from '@angular/router';
import { DealsComponent } from './deals.component';

import { DealsListComponent } from './deals-list.component';
import { DealsManageComponent } from './deals-manage.component';

const ROUTES: Route[] = [
    {
        path: '',
        component: DealsComponent,
        children: [
            { path: '', component: DealsListComponent, title: 'Deals & Offers' },
        ],
    },
    { path: 'manage', component: DealsManageComponent, title: 'Manage Deal' },
    { path: 'manage/:id', component: DealsManageComponent, title: 'Manage Deal' },
    { path: '**', redirectTo: '' },
];

@NgModule({
    declarations: [],
    imports: [
        DealsListComponent,
        DealsManageComponent,
        DealsComponent,
        RouterModule.forChild(ROUTES),
    ],
})
export class DealsModule {}
